package sn.kibaru;
import org.junit.jupiter.api.*;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.mock.web.MockHttpSession;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import java.util.*;
import java.math.BigDecimal;
import com.fasterxml.jackson.databind.ObjectMapper;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:aztests;MODE=PostgreSQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","shop.uploads=./target/test-uploads","shop.origin=http://localhost:4201"})
@AutoConfigureMockMvc @Transactional
class ShopIntegrationTest {
 @Autowired MockMvc mvc; @Autowired JdbcTemplate db; @Autowired ObjectMapper json; @Autowired OrderService orders; @Autowired ExchangeService exchange;
 final String origin="http://localhost:4201";
 long[] product(int stock){long cat=db.queryForObject("SELECT id FROM category ORDER BY id LIMIT 1",Long.class);String sku=UUID.randomUUID().toString();db.update("INSERT INTO product(name,sku,category_id,price,price_mad,price_xof,stock,status,image) VALUES('Babouches',?,?,0,199.50,12000,?,'published','/assets/az-mode.png')",sku,cat,stock);long id=db.queryForObject("SELECT id FROM product WHERE sku=?",Long.class,sku);db.update("INSERT INTO product_variant(product_id,sku,size,color,stock) VALUES(?,?,'42','Marron',?)",id,sku+"-42",stock);return new long[]{id,db.queryForObject("SELECT id FROM product_variant WHERE product_id=?",Long.class,id)};}
 void customer(String email){db.update("INSERT INTO shop_user(name,email,password_hash) VALUES('Client',?,'unused')",email);}
 Requests.Order request(long[] p,String currency){return new Requests.Order(List.of(new Requests.Item(p[0],p[1],2)),"Client","+221776722701","",new BigDecimal(currency.equals("MAD")?"399.00":"24000"),currency,"delivery","Rue de test 1, Rabat");}
 String create(long[] p,String currency){customer("client@example.com");var result=orders.create("client@example.com",UUID.randomUUID().toString(),request(p,currency));return ((Map<?,?>)result.get("order")).get("id").toString();}
 @Test void catalogCurrencyFiltersVariantsAndSecurity()throws Exception{product(4);mvc.perform(get("/api/products").param("currency","MAD").param("max","200")).andExpect(status().isOk()).andExpect(jsonPath("$.total").value(1)).andExpect(jsonPath("$.items[0].price").value(199.5)).andExpect(jsonPath("$.items[0].variants[0].size").value("42"));mvc.perform(get("/api/products").param("currency","XOF")).andExpect(jsonPath("$.items[0].price").value(12000));mvc.perform(get("/api/products").param("currency","EUR")).andExpect(status().isBadRequest());mvc.perform(get("/api/orders")).andExpect(status().isUnauthorized());mvc.perform(get("/api/admin/products").with(user("client").roles("CUSTOMER"))).andExpect(status().isForbidden());mvc.perform(post("/api/auth/login").header("Origin",origin).contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(post("/api/auth/login").with(csrf()).header("Origin","https://wrong.example").contentType("application/json").content("{}")).andExpect(status().isForbidden());}
 @Test void registrationSessionAndNoRoleInjection()throws Exception{var response=mvc.perform(post("/api/auth/register").with(csrf()).header("Origin",origin).contentType("application/json").content(json.writeValueAsString(Map.of("name","Amina","email","amina@example.com","phone","+221776722701","password","Test-password-long-1234")))).andExpect(status().isCreated()).andExpect(jsonPath("$.user.role").value("customer")).andReturn();mvc.perform(get("/api/session").session((MockHttpSession)response.getRequest().getSession(false))).andExpect(jsonPath("$.user.email").value("amina@example.com"));mvc.perform(post("/api/auth/register").with(csrf()).header("Origin",origin).contentType("application/json").content("{\"name\":\"Bad\",\"email\":\"bad@example.com\",\"password\":\"Test-password-long-1234\",\"role\":\"admin\"}")).andExpect(status().isBadRequest());}
 @Test void orderCurrencyIdempotencyTotalsAndOwnership()throws Exception{var p=product(6);customer("client@example.com");customer("other@example.com");String key=UUID.randomUUID().toString();String body=json.writeValueAsString(request(p,"MAD"));var first=mvc.perform(post("/api/orders").with(user("client@example.com")).with(csrf()).header("Origin",origin).header("Idempotency-Key",key).contentType("application/json").content(body)).andExpect(status().isOk()).andExpect(jsonPath("$.order.currency").value("MAD")).andExpect(jsonPath("$.order.total").value(399)).andExpect(jsonPath("$.order.history[0].status").value("awaiting_confirmation")).andExpect(jsonPath("$.whatsapp_url").value(org.hamcrest.Matchers.startsWith("https://wa.me/221776722701"))).andReturn();String id=json.readTree(first.getResponse().getContentAsString()).path("order").path("id").asText();mvc.perform(post("/api/orders").with(user("client@example.com")).with(csrf()).header("Origin",origin).header("Idempotency-Key",key).contentType("application/json").content(body)).andExpect(jsonPath("$.order.id").value(id));Assertions.assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM shop_order",Integer.class));mvc.perform(get("/api/orders/"+id).with(user("other@example.com"))).andExpect(status().isNotFound());mvc.perform(get("/api/orders").with(user("other@example.com"))).andExpect(jsonPath("$.total").value(0));mvc.perform(post("/api/orders").with(user("client@example.com")).with(csrf()).header("Origin",origin).header("Idempotency-Key",UUID.randomUUID().toString()).contentType("application/json").content(body.replace("399.00","1.00"))).andExpect(status().isConflict());}
 @Test void stockTransitionsAndSeparateCurrencyAnalytics()throws Exception{var p=product(3);String id=create(p,"XOF");orders.status(id,"confirmed");orders.status(id,"confirmed");Assertions.assertEquals(1,db.queryForObject("SELECT stock FROM product_variant WHERE id=?",Integer.class,p[1]));mvc.perform(get("/api/admin/analytics").param("currency","XOF").with(user("admin").roles("ADMIN"))).andExpect(status().isOk()).andExpect(jsonPath("$.summary.orders").value(1)).andExpect(jsonPath("$.summary.revenue").value(24000));mvc.perform(get("/api/admin/analytics").param("currency","MAD").with(user("admin").roles("ADMIN"))).andExpect(jsonPath("$.summary.orders").value(0));Assertions.assertThrows(ApiException.class,()->orders.status(id,"delivered"));orders.status(id,"preparing");orders.status(id,"cancelled");Assertions.assertEquals(3,db.queryForObject("SELECT stock FROM product_variant WHERE id=?",Integer.class,p[1]));Assertions.assertEquals(4,db.queryForObject("SELECT COUNT(*) FROM order_event WHERE order_id=?",Integer.class,id));}
 @Test void oversellingAndStaleStockEditsAreRejected()throws Exception{var p=product(1);Assertions.assertThrows(ApiException.class,()->orders.quote(request(p,"MAD").items(),"MAD"));mvc.perform(patch("/api/admin/products/"+p[0]+"/stock").with(user("admin").roles("ADMIN")).with(csrf()).header("Origin",origin).contentType("application/json").content(json.writeValueAsString(Map.of("variant_id",p[1],"stock",4,"version",0,"reason","Réception")))).andExpect(status().isOk());mvc.perform(patch("/api/admin/products/"+p[0]+"/stock").with(user("admin").roles("ADMIN")).with(csrf()).header("Origin",origin).contentType("application/json").content(json.writeValueAsString(Map.of("variant_id",p[1],"stock",2,"version",0,"reason","Obsolète")))).andExpect(status().isConflict());Assertions.assertEquals(4,db.queryForObject("SELECT stock FROM product_variant WHERE id=?",Integer.class,p[1]));}
 @Test void passwordResetUnconfiguredAndInvalidTokens()throws Exception{mvc.perform(get("/api/auth/password-reset/config")).andExpect(jsonPath("$.enabled").value(false));mvc.perform(post("/api/auth/forgot-password").with(csrf()).header("Origin",origin).contentType("application/json").content("{\"email\":\"client@example.com\"}")).andExpect(status().isServiceUnavailable());mvc.perform(post("/api/auth/reset-password").with(csrf()).header("Origin",origin).contentType("application/json").content("{\"token\":\"invalid-token\",\"password\":\"A-new-password-1234\"}")).andExpect(status().isBadRequest());}
 @Test void automatedRateRoundingAndReferenceOrderingBlock(){var p=product(10);exchange.applyRate(new BigDecimal("60.1234"),java.time.Instant.now());Assertions.assertEquals(11995,db.queryForObject("SELECT price_xof FROM product WHERE id=?",Long.class,p[0]));db.update("UPDATE product SET reference_only=TRUE WHERE id=?",p[0]);Assertions.assertThrows(ApiException.class,()->orders.quote(request(p,"MAD").items(),"MAD"));}

 @Test void guestCheckoutValidatesTotalAndIsIdempotent()throws Exception{
  var p=product(4);String key=UUID.randomUUID().toString();String body=json.writeValueAsString(request(p,"XOF"));
  var first=mvc.perform(post("/api/guest-orders").with(csrf()).header("Origin",origin).header("Idempotency-Key",key).contentType("application/json").content(body)).andExpect(status().isOk()).andExpect(jsonPath("$.order.currency").value("XOF")).andExpect(jsonPath("$.order.total").value(24000)).andExpect(jsonPath("$.whatsapp_url").value(org.hamcrest.Matchers.startsWith("https://wa.me/221776722701"))).andExpect(jsonPath("$.order.guest_key").doesNotExist()).andReturn();
  String id=json.readTree(first.getResponse().getContentAsString()).path("order").path("id").asText();
  mvc.perform(post("/api/guest-orders").with(csrf()).header("Origin",origin).header("Idempotency-Key",key).contentType("application/json").content(body)).andExpect(jsonPath("$.order.id").value(id));
  Assertions.assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM shop_order",Integer.class));
  mvc.perform(get("/api/orders/"+id)).andExpect(status().isUnauthorized());
  mvc.perform(post("/api/guest-orders").with(csrf()).header("Origin",origin).header("Idempotency-Key",UUID.randomUUID().toString()).contentType("application/json").content(body.replace("24000","1"))).andExpect(status().isConflict());
  mvc.perform(post("/api/guest-orders").header("Origin",origin).header("Idempotency-Key",key).contentType("application/json").content(body)).andExpect(status().isForbidden());
 }
}
